package space.glidetv.launcher;
import android.app.ActivityManager;import android.content.Context;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.Locale;
public final class UsageMeters extends LinearLayout {
 private final Handler handler=new Handler(Looper.getMainLooper());private final TextView ram,storage;private final Bar ramBar,storageBar;private boolean running;private LinearLayout ramControl;
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 public UsageMeters(Context c){super(c);setOrientation(HORIZONTAL);setClipChildren(false);setClipToPadding(false);ram=new TextView(c);storage=new TextView(c);ramBar=new Bar(c);storageBar=new Bar(c);addMeter(ram,ramBar);addMeter(storage,storageBar);}
 private void addMeter(TextView title,Bar bar){LinearLayout col=new LinearLayout(getContext());col.setOrientation(VERTICAL);title.setTextSize(9);title.setTextColor(0xffc6d4e6);title.setSingleLine(true);col.addView(title,new LinearLayout.LayoutParams(-1,dp(13)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(3));bp.topMargin=dp(4);col.addView(bar,bp);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(137),dp(24));cp.setMarginEnd(dp(18));addView(col,cp);if(title==ram){ramControl=col;col.setFocusable(true);col.setClickable(true);col.setContentDescription("RAM usage. Open memory details and cleanup.");col.setOnFocusChangeListener((v,f)->{v.setScaleX(1);v.setScaleY(1);title.setTextColor(f?0xffffffff:0xffc6d4e6);bar.setAlpha(f?1:.8f);});}}
 private final Runnable update=new Runnable(){public void run(){if(!running)return;try{ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)getContext().getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(m);int memory=(int)(100*(m.totalMem-m.availMem)/m.totalMem);StatFs s=new StatFs(Environment.getDataDirectory().getPath());int used=(int)(100*(s.getTotalBytes()-s.getAvailableBytes())/s.getTotalBytes());ram.setText(String.format(Locale.US,"RAM  %d%%  ·  %.1f GB free",memory,m.availMem/1073741824d));storage.setText(String.format(Locale.US,"STORAGE  %d%%  ·  %.0f GB free",used,s.getAvailableBytes()/1073741824d));ramBar.set(memory);storageBar.set(used);}catch(Exception ignored){}handler.postDelayed(this,5000);}};
 public void setOnRamClickListener(View.OnClickListener listener){ramControl.setOnClickListener(listener);}
 public void start(){running=true;handler.removeCallbacks(update);update.run();}public void stop(){running=false;handler.removeCallbacks(update);}
 private static final class Bar extends View {final Paint p=new Paint(3);float percent;Bar(Context c){super(c);}void set(int v){percent=v/100f;invalidate();}@Override public void onDraw(Canvas c){float h=getHeight();p.setColor(0x30ffffff);c.drawRoundRect(0,0,getWidth(),h,h,h,p);p.setColor(percent>.9?0xffffae89:0xffb5d9ef);c.drawRoundRect(0,0,getWidth()*percent,h,h,h,p);}}
}
